  "viewpoint": {
    "person": "third",
    "character": "佐倉ヒナ",
    "aliases": ["ヒナ"],
    "pronouns": []
  },
  "narrator": {
    "knows_ja": "佐倉ヒナが見たこと、測ったこと、聞いたこと、手に取ったものだけを知る。黒沢やサダの内心は、視線・手つき・言いよどみとして外から描く。既に死んでいる佐倉ツカサの内心や、ヒナのいない場所での会話は語らない。"
  },
  "sample": "八時五十七分。観測室の窓を押し開けると、風が紙の端を持ち上げた。ヒナは風向計の矢を読み、風速計の羽根が回るのを数える。北、三・二。日誌の昨日の欄は北、三・四だった。鉛筆を削ってから、彼女は数字を書き入れた。",
  "banned": [
    {"id": "b1", "pattern": "運命", "message_ja": "観測も閉鎖も人の判断で動く話なので、運命に預けると選択の重みが消える。"},
    {"id": "b2", "pattern": "奇跡", "message_ja": "閉鎖は覆らない。覆らないことを書く話なので、奇跡で回収しない。"},
    {"id": "b3", "pattern": "涙が", "message_ja": "感情は数字と道具の手触りに預ける。涙で処理すると、日誌の一行の意味が薄まる。"},
    {"id": "b4", "pattern": "心が読める", "message_ja": "語り手はヒナの外側しか知らない。他人の内心を地の文で断定しない。"}
  ],
  "notes": "地の文は常体。時刻は「八時五十七分」の形、風速は「三・二」の形で統一する。台詞は、ヒナと黒沢は標準語、サダとツカサは東北寄りの語尾（〜だべ は使わず、〜だ/〜ねぇ）にする。"
}
